/**
 * Where a project generated by `nest new` points before it is connected: the
 * hosted demo, which shows what the dashboard will look like.
 */
export const DEMO_URL = "https://www.observe-demo.nestjs.com/dashboard";
export const SIGN_UP_URL = "https://observe.nestjs.com";

/**
 * The command that connects a project in one step: it signs the developer in,
 * writes the key pair into `.env` and makes the start scripts load it.
 */
export const LINK_COMMAND = "npx @nestjs/observe link";

/** The variables `ObserveModule` reads a key pair from when its options leave it out. */
const KEY_VARIABLES = "OBSERVE_APP_KEY and OBSERVE_APP_SECRET";

export interface CredentialsNotice {
  level: "log" | "warn";
  message: string;
}

/**
 * The one line the agent says at start-up when it has no key pair it can send
 * with, so it sends nothing.
 *
 * Two situations look alike from inside the process and want opposite advice.
 * A project fresh from `nest new` still holds the scaffolded placeholders:
 * the fix is to connect it, which `npx @nestjs/observe link` does in one
 * step. A deployed process with the same placeholders, or with nothing at
 * all, is almost always a project that was connected on a laptop: link keeps
 * the pair in `.env`, which is git-ignored and which `node dist/main` never
 * loads, so production needs the two variables set where it runs. Telling
 * that person to create an account sends them looking for something they
 * already have, so under `NODE_ENV=production` the notice names the
 * variables instead.
 *
 * @param scaffold the options still hold `nest new`'s placeholders
 * @param unset which half of the pair is missing, when the options hold no
 * placeholders but lack a key, a secret or both
 */
export function describeMissingCredentials(input: {
  scaffold: boolean;
  unset?: "both" | "appKey" | "appSecret";
  production: boolean;
}): CredentialsNotice {
  if (input.production) {
    const state = input.scaffold
      ? "appKey and appSecret are still the placeholders from nest new"
      : `${describeUnset(input.unset)} not set`;
    return {
      level: "warn",
      message:
        `Observe is installed but sends nothing: ${state}. ` +
        `Set ${KEY_VARIABLES} in this environment, then restart the process - ` +
        `${LINK_COMMAND} keeps the pair in .env, which is not deployed. ` +
        `The pair is on your project's API Keys page at ${SIGN_UP_URL}.`,
    };
  }

  if (input.scaffold) {
    return {
      level: "log",
      message:
        `Observe is installed but not connected yet: appKey and appSecret are still the placeholders from nest new, so no telemetry is sent. ` +
        `Run ${LINK_COMMAND} in this project to connect it, or see what this app will look like first: ${DEMO_URL}`,
    };
  }

  // Said as a warning: a project that names no placeholders was wired by
  // hand, so a missing half is configuration that did not arrive.
  return {
    level: "warn",
    message:
      `Observe is installed but sends nothing: ${describeUnset(input.unset)} not set, and the hosted collector accepts no telemetry without a key and a secret. ` +
      `If they come from the environment, check that ${KEY_VARIABLES} reach this process, then restart it. ` +
      `To get a pair, run ${LINK_COMMAND} or create one at ${SIGN_UP_URL}.`,
  };
}

function describeUnset(
  unset: "both" | "appKey" | "appSecret" = "both",
): string {
  return unset === "both"
    ? "appKey and appSecret are"
    : unset === "appKey"
      ? "appKey is"
      : "appSecret is";
}
